/**
 * nexus-browser-doctor — show what the local browser needs on this machine; with --install, install all of it (src/install.ts — the
 * same installer `cortex setup` and `cortex browser install` use). Running --install IS the approval; at a terminal sudo may ask for a
 * password, without one nothing prompts and whatever cannot be installed silently is reported with the command to run.
 *   Core (default backend):  Node ≥ 20, Chrome/Chromium
 *   Sandbox backend:         python3 + patchright, Xvfb (its own display :99), xdotool, x11vnc + websockify (live view)
 *   Extras:                  uBlock Origin Lite + Consent-O-Matic, pymupdf / pdfplumber / beautifulsoup4 (pdf skills), pdf2htmlEX (optional)
 */
import { checkAll, installAll, readiness } from './install.js';

const install = process.argv.includes('--install');
if (install) {
  const r = await installAll({ interactive: !!process.stdin.isTTY && !!process.stdout.isTTY, log: (l) => console.log(l) });
  for (const d of r.done) console.log(`  installed: ${d}`);
  for (const m of r.manual) console.log(`  NOT installed — ${m}`);
}
const rows = checkAll();
const pad = (s: string, n: number) => (s.length > n ? s.slice(0, n - 1) + '…' : s.padEnd(n));
console.log(`\nnexus-browser doctor — ${process.platform}\n`);
for (const r of rows) console.log(`${r.ok ? '  ok ' : r.optional ? '  -- ' : '  NO '} ${pad(r.area, 11)} ${pad(r.item, 46)} ${r.ok ? '' : r.fix ?? ''}`);
const ready = readiness(rows);
console.log(`\ncore tools: ${ready.core ? 'READY' : 'NOT READY'} · sandbox backend: ${ready.sandbox ? 'READY' : 'NOT READY'}${install ? '' : ' · run with --install to install everything'}`);
process.exit(ready.core ? 0 : 1);
